-- Rifts World Book 26: Dinosaur Swamp, batch 2: the gear.
-- 157 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~248-dinosaur-swamp-gear.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
-- WHAT IS HERE (apps/character-creator/docs/surveys/dinosaur-swamp.md, plan step 2):
--
--   natural toxins             printed 43-44     5 rows (Lankton's Knot Acid in 3 sizes)
--   natural medicines          printed 44-45     2 rows (no price printed)
--   synthetic medicines        printed 45-47     8 rows (the survey counted 3)
--   Ghillie Suit, Homespun     printed 59, 63    2 rows
--   Viggo's custom firearms    printed 74-76     3 rows
--   barbarian weapons          printed 76-77     6 rows (club in 3 sizes, whip in 2)
--   SteelTree                  printed 78-82    58 rows (one per table line)
--   Eco-Wizard items           printed 84-96    29 rows (the survey counted 28)
--   Techno-Wizard equipment    printed 96-99    27 rows (14 Med-Shooter crystals)
--   Necromancy items           printed 100-101  17 rows (one per animal-type line)
--
-- ALL ARE NEW: catalog-diff --table gear --remote, 2026-10-20, 0 matched by name
-- or slug; its one alias match (SteelTree Forged Armor: Helmet -> Helmet) is a
-- different item. NOT ADDED: the Vibro-Spear and Vibro-Axe (printed 77), held from
-- Spirit West and Warlords of Russia; the book's own figures (7-10 lbs,
-- 1D6/2D4/2D6 M.D. by blade, 10,000-15,000 credits) are left to those rows.
-- The four barbarian versions, five diseases, residents and Dimensional Shifting
-- are left by Nate's ruling D18 (2026-10-19).
--
-- NAMES. Eco-Wizard items carry "EW " and an ew- slug, the convention Rifts World
-- Book 27 already shipped; Techno-Wizard items "TW "; necromantic parts
-- "Necromancy: ". The book's Homespun Armor is slugged dinosaur-swamp-homespun-armor
-- beside Australia's homespun-* price list.
--
-- A RANGE IS STORED BY ITS LOW END (cost, weight_lbs, mdc); cost_note and the
-- description give the whole range. M.D.C. THAT IS ROLLED (2D6+20) leaves mdc
-- empty and is stated in the description. NULL cost is a finished row: the
-- natural medicines, the Ghillie Suit, the Predator Mask and SteelTree Twig Armor
-- print no credit price, and the Necromancy parts print only a P.P.E. cost.
--
-- FIGURES THE BOOK PRINTS TWICE OR ODDLY, stored as printed and noted in the row:
-- Seep Fern Blood (1,000 a dose on printed 43; 100 a vial on printed 40); Skin,
-- Skull & Plate Armor (6D6+68 and 6D6+66 on printed 92); the Provider rifle's
-- 1D6 M.D.; the Herbivore Tail's "1D4 M.D.C."; Qink Toxin's "up to 8,000" is a
-- ceiling and stores NULL.
--
-- Every figure was read off the cache (a scan, offset +1 per scripts/books.json),
-- checked on renders by the extraction, and every row was checked by
-- book-reconcile in three slices (40-47/59/63/74-76, 77-89, 90-101).

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('seep-fern-blood', 'Seep Fern Blood', 'rifts', 'gear', NULL, 1000, '1,000 credits each for a two-dose vial (printed 43); the Seep Fern entry (printed 40) prices it at 100 credits a single-dose vial or 900 for ten. Both are printed; the toxin section is stored.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Knockout secretion of the Seep Fern, plentiful. Victim saves vs non-lethal poison (16 or higher) or falls unconscious and unfeeling for 1D4 hours, then wakes stiff and sore but unharmed. Works inhaled, eaten or injected. Coats arrowheads and weapons for taking prisoners and hunting; a possible surgical anesthetic. Potency fades to nothing within 12 days (printed 40).', 'Rifts World Book 26: Dinosaur Swamp p.43', NULL),
  ('qink-toxin', 'Qink Toxin', 'rifts', 'gear', NULL, NULL, 'Up to 8,000 credits for a single-dose vial; a ceiling, not a fixed price.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Paralytic toxin of the Qink plant, extremely difficult to harvest. Victim saves vs poison (14 or higher) or loses all feeling in the limb or body area struck (location chart under the Qink plant, printed 39), staying conscious. Swallowed it only numbs mouth, throat and stomach: -1 initiative and -1 to strike, parry and dodge for 2D6x10 minutes. Best injected. Used as a tranquilizer, local anesthetic and torture tool; tiny doses are an anti-spasm drug and painkiller. Rarely used on game because it lingers in the meat.', 'Rifts World Book 26: Dinosaur Swamp p.43-44', NULL),
  ('lanktons-knot-acid-egg', 'Lankton''s Knot Acid (egg-sized container)', 'rifts', 'weapon', NULL, 6000, '6,000-10,000 credits.', '1D6 every five seconds for 1D4 melee rounds', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Corrosive honey-like acid of Lankton''s Knot, thrown or slung in a glass jar (glass is the only common safe container). Does its damage every five seconds for 1D4 melee rounds (x3 per melee round): S.D.C. to humans, M.D. to dragons and demons, depending on the surface hit; inorganic material takes one third. M.D.C. metal and inorganic M.D.C. material take 3D6 M.D. per 24 hours of soaking. Scraping it off does another 1D6; citrus juice removes it; brushing it spreads it. No medicinal use.', 'Rifts World Book 26: Dinosaur Swamp p.44', NULL),
  ('lanktons-knot-acid-orange', 'Lankton''s Knot Acid (orange-sized container)', 'rifts', 'weapon', NULL, 15000, '15,000-20,000 credits.', '2D6 every five seconds for 1D4 melee rounds', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Corrosive honey-like acid of Lankton''s Knot, thrown or slung in a glass jar (glass is the only common safe container). Does its damage every five seconds for 1D4 melee rounds (x3 per melee round): S.D.C. to humans, M.D. to dragons and demons, depending on the surface hit; inorganic material takes one third. M.D.C. metal and inorganic M.D.C. material take 3D6 M.D. per 24 hours of soaking. Scraping it off does another 1D6; citrus juice removes it; brushing it spreads it. No medicinal use.', 'Rifts World Book 26: Dinosaur Swamp p.44', NULL),
  ('lanktons-knot-acid-grapefruit', 'Lankton''s Knot Acid (grapefruit-sized container)', 'rifts', 'weapon', NULL, 35000, '35,000-40,000 credits.', '4D6 every five seconds for 1D4 melee rounds', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Corrosive honey-like acid of Lankton''s Knot, thrown or slung in a glass jar (glass is the only common safe container). Does its damage every five seconds for 1D4 melee rounds (x3 per melee round): S.D.C. to humans, M.D. to dragons and demons, depending on the surface hit; inorganic material takes one third. M.D.C. metal and inorganic M.D.C. material take 3D6 M.D. per 24 hours of soaking. Scraping it off does another 1D6; citrus juice removes it; brushing it spreads it. No medicinal use.', 'Rifts World Book 26: Dinosaur Swamp p.44', NULL),
  ('uzain-plant', 'Uzain Plant', 'rifts', 'gear', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A medicinal plant: about 6 internal doses (seed cones) or 2 paste applications for a knife-gash wound. Eaten: lasts 8 hours, +2 vs disease, +2 to save vs poison, heals 2D6 points of illness damage. Paste: +4 vs disease for all the wounds of the injured character (enough paste to treat them all), no poison protection. Paste and a dose together: at most +6 vs disease and +4 vs poison, healing 2D6+3. Extra doses cause cramps and diarrhea, negate the healing and do 1D6 S.D.C.; extra paste is only wasted. No price printed.', 'Rifts World Book 26: Dinosaur Swamp p.44', NULL),
  ('darach-tree-extract', 'Darach Tree Extract', 'rifts', 'gear', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Medicine and poison from the Darach Tree. A dose needs a Holistic Medicine or M.D. roll (Forensics or Chemistry at the G.M.''s option); a failure is 01-50 too weak, 51-00 too strong (save vs poison 13+ or unconscious 4D6 hours and 4D6 direct to Hit Points). As medicine, 12 hours: skill penalties from pain or fever halved, one lost melee action returned, attribute and combat penalties halved; no help for hallucinations or Hit Point damage; more than one dose at a time is poisonous. As poison (one dose coats four arrowheads or a small knife): save vs lethal poison 14+ per dose; a save costs one action and -1 to strike, parry and dodge for 1D4 rounds; a failure gives 01-30 unconsciousness (2D6+10 minutes), 2D6 direct to Hit Points, two actions per melee and combat bonuses halved, per dose and cumulative, for 1D6 rounds per dose. No price printed.', 'Rifts World Book 26: Dinosaur Swamp p.44-45', NULL),
  ('penicillin', 'Penicillin', 'rifts', 'gear', NULL, 100, '100 credits for a bottle of 20 pill doses; 250 for an IV solution. Common; up to 10x higher far from trade.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Broad spectrum antibiotic. Pill: +1 vs disease for 12 hours, heals 1D4 illness damage. IV bag: +2 vs disease for 24 hours, heals 1D6+1 if fully dripped. One extra dose gives mild nausea; two or more give cramps and diarrhea, negate the healing and do 1D6 direct to Hit Points.', 'Rifts World Book 26: Dinosaur Swamp p.45', NULL),
  ('pandisporin', 'Pandisporin', 'rifts', 'gear', NULL, 200, '200 credits for a bottle of 12 doses; 600 for an IV. Good availability; up to 10x or more far from trade.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Broad spectrum antibiotic. Pill: +2 vs disease for 12 hours, heals 1D6+2. IV: +3 vs disease for 30 hours, heals 1D6+4. Overdose: severe cramps, -1 vs disease for 6 hours, negated healing, 1D6+3 direct to Hit Points.', 'Rifts World Book 26: Dinosaur Swamp p.45', NULL),
  ('necromycin', 'Necromycin', 'rifts', 'gear', NULL, 5000, '5,000 credits for a bottle of six doses; 9,000 for an IV. Rare; up to 20x or more far from trade.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Last-resort broad spectrum antibiotic. Pill: +5 vs disease for 8 hours, but does 2D6 S.D.C. (1D6 to Hit Points with no S.D.C.) and 1D6 direct to Hit Points. IV: +7 vs disease for 12 hours, 2D6+3 direct to Hit Points. Overdose is usually fatal: bonuses negated, -4 vs disease for 12 hours, 4D6 direct to Hit Points.', 'Rifts World Book 26: Dinosaur Swamp p.45-46', NULL),
  ('cadaniricin', 'Cadaniricin', 'rifts', 'gear', NULL, 50, '50 credits for a bottle of 30 pills; 100 for a spray or salve of 50 applications. Common; up to 5x far from trade.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Narrow spectrum antifungal; pill, salve or spray. +2 vs disease caused by a fungus only. No harm and no extra benefit from an overdose.', 'Rifts World Book 26: Dinosaur Swamp p.46', NULL),
  ('dentiricin', 'Dentiricin', 'rifts', 'gear', NULL, 6000, '6,000 credits for a tube of five doses. Extremely rare; up to 10x far from trade.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Narrow spectrum antibiotic salve, known only in Dinosaur Swamp. One dose on the wound gives +4 vs disease from Blacktooth cuts only and halves all infection penalties three hours after application; lasts six hours. No overdose problem.', 'Rifts World Book 26: Dinosaur Swamp p.46', NULL),
  ('tributomol', 'Tributomol', 'rifts', 'gear', NULL, 60, '60 credits for a bottle of 20 doses; 90 for an IV. Excellent availability; up to 3x far from trade.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Painkiller; pill or IV bag. Skill penalties reduced by 25% (a -20% becomes -15%), attribute and combat penalties halved, for 12 hours a pill or 24 hours as IV. A double dose doubles the effect and does 1D6+3 direct to Hit Points; a triple dose triples it, does 2D6+4 direct and carries a 25% chance of permanent organ damage.', 'Rifts World Book 26: Dinosaur Swamp p.46', NULL),
  ('penthydrocodine', 'Penthydrocodine ("5-Cod")', 'rifts', 'gear', NULL, 5000, '5,000 credits for a bottle of 10 doses; 7,000 for an IV. Poor availability; up to 10x far from trade or in a medical crisis.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Strong painkiller; pill or IV. Cuts all pain penalties by 75% and doubles recovery effects taken as directed; 8 hours a pill, 12 as IV. Causes heavy sleep for 1D4 hours (1D4x10 minutes for Juicers). 15% of patients save vs non-lethal poison 16+ or become addicted. Overdose: double side effects (sleep 2D4 hours) and 01-60 chance of falling to zero Hit Points and a coma unnoticed; Juicers can fight to 30 below zero first.', 'Rifts World Book 26: Dinosaur Swamp p.46-47', NULL),
  ('hydrating-salts', 'Hydrating Salts', 'rifts', 'gear', NULL, 5, '5 credits a single-dose packet; a crate of 10 packets 50. Fairly common; rarely above twice normal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'One packet mixed with water heals 1D6 Hit Points of dehydration damage; at most two doses per 24 hours. Overdose: bloating, -1 initiative and -1 to dodge.', 'Rifts World Book 26: Dinosaur Swamp p.47', NULL),
  ('ghillie-suit', 'Ghillie Suit', 'rifts', 'gear', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Layered strips of dyed burlap that break up the human outline against the naked eye and enhanced optics, but not thermo-imaging, magic or psionic detection. The Dinosaur Hunter''s own hand-made suit gives +10% to Prowl, Camouflage and Blend; any other wearer gets +5%. Works only after a successful roll on one of those skills. No price printed.', 'Rifts World Book 26: Dinosaur Swamp p.59', NULL),
  ('dinosaur-swamp-homespun-armor', 'Homespun Armor (Dinosaur Swamp)', 'rifts', 'armor', NULL, 12000, '12,000-20,000 credits or the equivalent in trade.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Piecemeal non-environmental body armor of dinosaur hide and bone, or scraps of M.D.C. from high-tech armor and vehicles, worn by Wild Knives Warriors. M.D.C. IS ROLLED, so the mdc column is empty: main body 26+2D6, limbs 1D10+6, helmet 2D6+30. -10% to Prowl, Swim and other skills needing free movement.', 'Rifts World Book 26: Dinosaur Swamp p.63', NULL),
  ('viggo-legacy-bolt-action-rifle', 'Legacy Bolt-Action Rifle', 'rifts', 'weapon', 7, 5000, '5,000 credits quality generic; 10,000 custom-made for the buyer. Ammunition 300 per box of 100.', '5D6 S.D.C.', 0, '2500 ft (762 m)', '5-round internal box magazine', 'Each shot takes two melee attacks (fire, then work the bolt)', NULL, NULL, NULL, 'One of Viggo''s custom firearms, a 30-06 billed as the most accurate rifle in the world; comes with scope brackets. +1 to strike on aimed shots for anyone, +2 for the person it was custom-made for. A natural 18-20 is a critical strike (double damage).', 'Rifts World Book 26: Dinosaur Swamp p.74-75', NULL),
  ('viggo-savage-pump-action-rifle', 'Savage Pump-Action Rifle', 'rifts', 'weapon', 9, 9500, '9,500 credits quality; 14,300 custom-made. Ammunition 400 per box of 100.', '4D6 S.D.C.', 0, '1700 ft (518 m)', '5-round detachable box magazine', 'One melee action per shot, pump included', NULL, NULL, NULL, 'One of Viggo''s custom firearms, in .300 Short Magnum. +1 to strike on aimed shots for anyone; the custom owner gets a further +1 on aimed shots. A natural 19 or 20 is a critical strike (double damage).', 'Rifts World Book 26: Dinosaur Swamp p.75', NULL),
  ('viggo-provider-breach-loading-rifle', 'Provider Single-Shot Breach Loading Rifle', 'rifts', 'weapon', 25, 11500, '11,500 credits quality; 16,000 custom-made. Ammunition 1,000 per box of 20.', '1D6 M.D.', 1, '4000 ft (1219 m)', 'Single shot', 'Single shot; three melee actions per shot', NULL, NULL, NULL, 'One of Viggo''s custom firearms, firing a .78 caliber (18 mm) steel-cased anti-armor round; the 1D6 M.D. is as printed. +1 to strike on aimed shots for anyone, +2 for the custom owner. A natural 18-20 is a critical strike doing triple damage. Recoil: a firer without W.P. Bolt-Action Rifle is stunned, takes 1D4 S.D.C. and loses the next melee action; with the skill, save vs pain 10+ or take 1D4 S.D.C. M.D.C. body armor stops the damage but not the lost action.', 'Rifts World Book 26: Dinosaur Swamp p.75-76', NULL),
  ('claw-gauntlets', 'Claw Gauntlets', 'rifts', 'weapon', 1, 250, '250 credits for a simple gauntlet, up to 1,000 for elaborate ones.', '2D6 S.D.C.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A heavy glove and forearm guard studded with claws, teeth or blades, a mundane version of the Eco-Wizard Bleeder Claws; many layouts. +1 to parry, +1 to disarm. A held or pinned opponent without M.D.C. armor takes 1D6 S.D.C. each time he tries to break the hold.', 'Rifts World Book 26: Dinosaur Swamp p.76', NULL),
  ('tooth-war-club-small', 'Tooth War Club (Small)', 'rifts', 'weapon', 2, 50, '50-100 credits.', '1D6 S.D.C.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A war club studded with dinosaur teeth. If poison-coated the victim saves vs lethal (14+) or non-lethal (16+) poison; dung on the teeth gives a 01-45 chance of infection within 24 hours unless cleaned and bandaged within 12. On a critical strike it leaves 1D4 teeth in the victim, for +1D6 damage and a need for treatment. Tooth or claw axes do similar damage; stone axes weigh 50% more.', 'Rifts World Book 26: Dinosaur Swamp p.76', NULL),
  ('tooth-war-club-medium', 'Tooth War Club (Medium)', 'rifts', 'weapon', 5, 200, '200-300 credits.', '2D6+2 S.D.C.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Mace-sized. A war club studded with dinosaur teeth. If poison-coated the victim saves vs lethal (14+) or non-lethal (16+) poison; dung on the teeth gives a 01-45 chance of infection within 24 hours unless cleaned and bandaged within 12. On a critical strike it leaves 1D4 teeth in the victim, for +1D6 damage and a need for treatment. Tooth or claw axes do similar damage; stone axes weigh 50% more.', 'Rifts World Book 26: Dinosaur Swamp p.76', NULL),
  ('tooth-war-club-large', 'Tooth War Club (Large)', 'rifts', 'weapon', 9, 400, '400-600 credits.', '3D6+3 S.D.C.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Baseball-bat-sized. A war club studded with dinosaur teeth. If poison-coated the victim saves vs lethal (14+) or non-lethal (16+) poison; dung on the teeth gives a 01-45 chance of infection within 24 hours unless cleaned and bandaged within 12. On a critical strike it leaves 1D4 teeth in the victim, for +1D6 damage and a need for treatment. Tooth or claw axes do similar damage; stone axes weigh 50% more.', 'Rifts World Book 26: Dinosaur Swamp p.76', NULL),
  ('tooth-spiked-bullwhip', 'Tooth Spiked Whip (Bullwhip)', 'rifts', 'weapon', 5, 200, '200-300 credits.', '2D6+2 S.D.C.', 0, 'Reach 12 ft (3.6 m)', NULL, NULL, NULL, NULL, NULL, 'A bullwhip set with teeth. +1 to strike, +2 to disarm, +2 to entangle. Can be swung on like a rope (two actions).', 'Rifts World Book 26: Dinosaur Swamp p.77', NULL),
  ('tooth-spiked-cat-o-nine-tails', 'Tooth Spiked Whip (Cat-o-Nine-Tails)', 'rifts', 'weapon', 5, 300, '300-400 credits.', '2D6 S.D.C. +1 per tail', 0, 'Reach 7 ft (2.1 m)', NULL, NULL, NULL, NULL, NULL, 'A many-tailed whip set with teeth; it has 1D4+5 strands, each adding +1 damage. +1 to parry; -3 to strike a moving target.', 'Rifts World Book 26: Dinosaur Swamp p.77', NULL),
  ('steeltree-tool-axe', 'SteelTree Forged Tool: Axe', 'rifts', 'gear', NULL, 100, 'Excellent availability.', '1D4 M.D. if used as a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A tool forged from SteelTree, sold on the open market at Char. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire. Any such tool used as a weapon does 1D4 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.78', NULL),
  ('steeltree-tool-hammer', 'SteelTree Forged Tool: Hammer', 'rifts', 'gear', NULL, 80, 'Excellent availability.', '1D4 M.D. if used as a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A tool forged from SteelTree, sold on the open market at Char. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire. Any such tool used as a weapon does 1D4 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.78', NULL),
  ('steeltree-tool-hinges', 'SteelTree Forged Tool: Hinges', 'rifts', 'gear', NULL, 200, 'Poor availability.', '1D4 M.D. if used as a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A tool forged from SteelTree, sold on the open market at Char. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire. Any such tool used as a weapon does 1D4 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.78', NULL),
  ('steeltree-tool-mallet-maul-large', 'SteelTree Forged Tool: Mallet/Maul (large)', 'rifts', 'gear', NULL, 400, 'Poor availability.', '1D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A tool forged from SteelTree, sold on the open market at Char. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire. Any such tool used as a weapon does 1D4 M.D.; the large mallet or maul does 1D6 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.78', NULL),
  ('steeltree-tool-nails', 'SteelTree Forged Tool: Nails', 'rifts', 'gear', NULL, 10, '10 credits per dozen. Good availability.', '1D4 M.D. if used as a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A tool forged from SteelTree, sold on the open market at Char. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire. Any such tool used as a weapon does 1D4 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.78', NULL),
  ('steeltree-tool-poker-rod', 'SteelTree Forged Tool: Poker/Rod', 'rifts', 'gear', NULL, 100, 'Good availability.', '1D4 M.D. if used as a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A tool forged from SteelTree, sold on the open market at Char. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire. Any such tool used as a weapon does 1D4 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.78', NULL),
  ('steeltree-tool-tongs-pliers', 'SteelTree Forged Tool: Tongs/Pliers', 'rifts', 'gear', NULL, 80, 'Fair availability.', '1D4 M.D. if used as a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A tool forged from SteelTree, sold on the open market at Char. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire. Any such tool used as a weapon does 1D4 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.78', NULL),
  ('steeltree-tool-scissors', 'SteelTree Forged Tool: Scissors', 'rifts', 'gear', NULL, 200, 'Good availability.', '1D4 M.D. if used as a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A tool forged from SteelTree, sold on the open market at Char. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire. Any such tool used as a weapon does 1D4 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.78', NULL),
  ('steeltree-tool-spoon-large', 'SteelTree Forged Tool: Spoon, Large', 'rifts', 'gear', NULL, 70, 'Good availability.', '1D4 M.D. if used as a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A tool forged from SteelTree, sold on the open market at Char. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire. Any such tool used as a weapon does 1D4 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.78', NULL),
  ('steeltree-tool-saw-hand', 'SteelTree Forged Tool: Saw, Hand', 'rifts', 'gear', NULL, 250, 'Poor availability.', '1D4 M.D. if used as a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A tool forged from SteelTree, sold on the open market at Char. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire. Any such tool used as a weapon does 1D4 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.78', NULL),
  ('steeltree-tool-saw-2-man', 'SteelTree Forged Tool: Saw, 2-man', 'rifts', 'gear', NULL, 500, 'Poor availability.', '1D4 M.D. if used as a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A tool forged from SteelTree, sold on the open market at Char. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire. Any such tool used as a weapon does 1D4 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.78', NULL),
  ('steeltree-tool-saw-hack', 'SteelTree Forged Tool: Saw, Hack', 'rifts', 'gear', NULL, 400, 'Poor availability.', '1D4 M.D. if used as a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A tool forged from SteelTree, sold on the open market at Char. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire. Any such tool used as a weapon does 1D4 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.78', NULL),
  ('steeltree-tool-scythe', 'SteelTree Forged Tool: Scythe', 'rifts', 'gear', NULL, 120, 'Fair availability.', '1D4 M.D. if used as a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A tool forged from SteelTree, sold on the open market at Char. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire. Any such tool used as a weapon does 1D4 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.78', NULL),
  ('steeltree-tool-spike-chisel', 'SteelTree Forged Tool: Spike/Chisel', 'rifts', 'gear', NULL, 50, 'Fair availability.', '1D4 M.D. if used as a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A tool forged from SteelTree, sold on the open market at Char. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire. Any such tool used as a weapon does 1D4 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.78', NULL);

