  ('steeltree-tool-shovel-rake', 'SteelTree Forged Tool: Shovel/Rake', 'rifts', 'gear', NULL, 110, 'Excellent availability.', '1D4 M.D. if used as a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A tool forged from SteelTree, sold on the open market at Char. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire. Any such tool used as a weapon does 1D4 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.78', NULL),
  ('steeltree-weapon-arrow-broadhead', 'SteelTree Forged Weapon: Arrow, Broadhead', 'rifts', 'weapon', 0.375, 200, NULL, '2 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Forged SteelTree, average length 2 in, weight 6 oz. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire; prices are market values at Char. Blades compare to Vibro-Blades and survive Supernatural Strength; sloppy work gives -1 to strike and -2 to parry. The arrowhead alone is M.D.C.: unless the shaft is SteelTree or other M.D.C. material the arrow is destroyed on impact. Toxin-coated heads are used on big game.', 'Rifts World Book 26: Dinosaur Swamp p.79', NULL),
  ('steeltree-weapon-arrow-target-head', 'SteelTree Forged Weapon: Arrow, Target Head', 'rifts', 'weapon', 0.25, 100, NULL, '1 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Forged SteelTree, average length 1.5 in, weight 4 oz. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire; prices are market values at Char. Blades compare to Vibro-Blades and survive Supernatural Strength; sloppy work gives -1 to strike and -2 to parry. The arrowhead alone is M.D.C.: unless the shaft is SteelTree or other M.D.C. material the arrow is destroyed on impact. Toxin-coated heads are used on big game.', 'Rifts World Book 26: Dinosaur Swamp p.79', NULL),
