  ('steeltree-weapon-mace-morning-star', 'SteelTree Forged Weapon: Mace/Morning Star', 'rifts', 'weapon', 6, 1000, NULL, '2D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Forged SteelTree, average length 2.5 ft, weight 6-8 lbs. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire; prices are market values at Char. Blades compare to Vibro-Blades and survive Supernatural Strength; sloppy work gives -1 to strike and -2 to parry.', 'Rifts World Book 26: Dinosaur Swamp p.79', NULL),
  ('steeltree-weapon-spear-short', 'SteelTree Forged Weapon: Spear, Short', 'rifts', 'weapon', 6, 850, NULL, '1D8 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Forged SteelTree, average length 4 ft. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire; prices are market values at Char. Blades compare to Vibro-Blades and survive Supernatural Strength; sloppy work gives -1 to strike and -2 to parry.', 'Rifts World Book 26: Dinosaur Swamp p.79', NULL),
  ('steeltree-weapon-spear-long', 'SteelTree Forged Weapon: Spear, Long', 'rifts', 'weapon', 8, 1000, NULL, '2D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Forged SteelTree, average length 8 ft. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire; prices are market values at Char. Blades compare to Vibro-Blades and survive Supernatural Strength; sloppy work gives -1 to strike and -2 to parry.', 'Rifts World Book 26: Dinosaur Swamp p.79', NULL),
  ('steeltree-weapon-sword-broad', 'SteelTree Forged Weapon: Sword, Broad', 'rifts', 'weapon', 5, 1600, NULL, '2D6+2 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Forged SteelTree, average length 3 ft, weight 5-6 lbs. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire; prices are market values at Char. Blades compare to Vibro-Blades and survive Supernatural Strength; sloppy work gives -1 to strike and -2 to parry.', 'Rifts World Book 26: Dinosaur Swamp p.79', NULL),
  ('steeltree-weapon-sword-long', 'SteelTree Forged Weapon: Sword, Long', 'rifts', 'weapon', 7, 2500, NULL, '3D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Forged SteelTree, average length 3-4 ft, weight 7-10 lbs. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire; prices are market values at Char. Blades compare to Vibro-Blades and survive Supernatural Strength; sloppy work gives -1 to strike and -2 to parry.', 'Rifts World Book 26: Dinosaur Swamp p.79', NULL),
  ('steeltree-weapon-sword-short', 'SteelTree Forged Weapon: Sword, Short', 'rifts', 'weapon', 3, 1200, NULL, '2D4 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Forged SteelTree, average length 2.5 ft, weight 3-4 lbs. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire; prices are market values at Char. Blades compare to Vibro-Blades and survive Supernatural Strength; sloppy work gives -1 to strike and -2 to parry.', 'Rifts World Book 26: Dinosaur Swamp p.79', NULL),
  ('steeltree-weapon-war-hammer', 'SteelTree Forged Weapon: War Hammer', 'rifts', 'weapon', 6, 1000, NULL, '2D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Forged SteelTree, average length 2.5 ft, weight 6-8 lbs. SteelTree, an alien tree of the South Carolina piedmont, forges into heavy M.D.C. material that takes 50% extra damage from M.D. fire, plasma and magic fire; prices are market values at Char. Blades compare to Vibro-Blades and survive Supernatural Strength; sloppy work gives -1 to strike and -2 to parry.', 'Rifts World Book 26: Dinosaur Swamp p.79', NULL),
  ('steeltree-short-bow', 'SteelTree Short Bow', 'rifts', 'weapon', 4, 3200, NULL, '1D6 M.D.', 1, '680 ft (207 m)', NULL, '2 to 8 (W.P. Archery and Targeting)', NULL, NULL, NULL, 'A forged SteelTree bow; -1 to strike. Needs P.S. 21+ (bionic 18, robotic 15, or any Supernatural Strength above 6). Normal S.D.C. arrows from it do 4D6 S.D.C. and shatter; explosive arrowheads do their explosive damage. Rate of fire per W.P. Archery and Targeting.', 'Rifts World Book 26: Dinosaur Swamp p.79', NULL),
  ('steeltree-long-bow', 'SteelTree Long Bow', 'rifts', 'weapon', 7, 7600, NULL, '3D6 M.D.', 1, '1000 ft (305 m)', NULL, '2 to 8 (W.P. Archery and Targeting)', NULL, NULL, NULL, 'A forged SteelTree bow; -2 to strike. Needs P.S. 21+ (bionic 18, robotic 15, or any Supernatural Strength above 6). Normal S.D.C. arrows from it do 4D6 S.D.C. and shatter; explosive arrowheads do their explosive damage. Rate of fire per W.P. Archery and Targeting.', 'Rifts World Book 26: Dinosaur Swamp p.79', NULL),
  ('steeltree-crossbow', 'SteelTree Crossbow', 'rifts', 'weapon', 10, 15200, NULL, '2D6 M.D.', 1, '1200 ft (366 m)', NULL, '2 to 8 (W.P. Archery and Targeting)', NULL, NULL, NULL, 'A rare forged SteelTree crossbow, made by Operators and the like; -1 to strike. Needs only P.S. 8. Normal S.D.C. bolts do 4D6 S.D.C. and shatter.', 'Rifts World Book 26: Dinosaur Swamp p.79', NULL),
  ('steeltree-root-rope', 'SteelTree M.D.C. Root Rope/Cable', 'rifts', 'gear', NULL, 2, '2 credits per foot at Char; the merchants are thinking of raising it three- or fourfold.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Aerial SteelTree roots as thick as ship rope and as strong as steel cable, found up to 15 ft up at the base of the trees; cannot be forged. 100 S.D.C. per foot (0.3 m), which equals 1 M.D.C. per foot.', 'Rifts World Book 26: Dinosaur Swamp p.79-80', NULL),
  ('steeltree-whip', 'SteelTree M.D. Whip', 'rifts', 'weapon', 5, 1000, '1,000-2,000 credits.', '1D4 M.D. against M.D. armor; 1D6 M.D. against the flesh of M.D. creatures', 1, '5-6 ft (1.5-1.8 m) long', NULL, NULL, NULL, NULL, NULL, 'A whip made from a young SteelTree seedling or branch, ideally no more than 5 lbs for a human. The tip goes brittle and breaks off after about six months; replace it within eight.', 'Rifts World Book 26: Dinosaur Swamp p.80', NULL),
  ('steeltree-forged-chain-mail', 'SteelTree Forged Armor: Chain Mail', 'rifts', 'armor', 50, 4000, 'Poor availability. A half suit is half the M.D.C. and half the cost, at -15%.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 40, 'Forged SteelTree armor: non-environmental, very heavy and hard to repair; a full suit gives -30% to Acrobatics, Gymnastics, Climbing, Swimming and Prowl. Custom orders take 3-6 weeks; poor to no availability outside Char.', 'Rifts World Book 26: Dinosaur Swamp p.80', NULL),
  ('steeltree-forged-scale-mail', 'SteelTree Forged Armor: Scale Mail', 'rifts', 'armor', 60, 7000, 'Poor availability. A half suit is half the M.D.C. and half the cost, at -15%.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 90, 'Forged SteelTree armor: non-environmental, very heavy and hard to repair; a full suit gives -30% to Acrobatics, Gymnastics, Climbing, Swimming and Prowl. Custom orders take 3-6 weeks; poor to no availability outside Char.', 'Rifts World Book 26: Dinosaur Swamp p.80', NULL),
  ('steeltree-forged-plate', 'SteelTree Forged Armor: Plate', 'rifts', 'armor', 70, 10000, 'Poor availability. A half suit is half the M.D.C. and half the cost, at -15%.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 150, 'Forged SteelTree armor: non-environmental, very heavy and hard to repair; a full suit gives -30% to Acrobatics, Gymnastics, Climbing, Swimming and Prowl. Custom orders take 3-6 weeks; poor to no availability outside Char.', 'Rifts World Book 26: Dinosaur Swamp p.80', NULL),
  ('steeltree-forged-helmet', 'SteelTree Forged Armor: Helmet', 'rifts', 'armor', 10, 2000, 'Good availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 60, 'Forged SteelTree armor: non-environmental, very heavy and hard to repair; a full suit gives -30% to Acrobatics, Gymnastics, Climbing, Swimming and Prowl. Custom orders take 3-6 weeks; poor to no availability outside Char.', 'Rifts World Book 26: Dinosaur Swamp p.80', NULL),
  ('steeltree-forged-shield', 'SteelTree Forged Armor: Shield', 'rifts', 'armor', 25, 4000, '4,000-8,000 credits. Good availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 40, 'Forged SteelTree armor: non-environmental, very heavy and hard to repair; a full suit gives -30% to Acrobatics, Gymnastics, Climbing, Swimming and Prowl. Custom orders take 3-6 weeks; poor to no availability outside Char. The shield has 40-80 M.D.C. (the low end stored).', 'Rifts World Book 26: Dinosaur Swamp p.80', NULL),
  ('steeltree-bark-armor-skullcap-helmet', 'SteelTree Bark Armor: Skullcap/Helmet', 'rifts', 'armor', 9, 1000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 25, 'Unforged armor of gray SteelTree bark, non-environmental, worn as a full suit or in pieces. -20% to Prowl and similar skills in a full suit, -10% in a half suit, -5% for helmet with arm and leg guards only. +5% to Camouflage. Price varies with availability and craftsmanship; basic plain prices at Char.', 'Rifts World Book 26: Dinosaur Swamp p.80', NULL),
  ('steeltree-bark-armor-shoulder-pieces', 'SteelTree Bark Armor: Shoulder Pieces', 'rifts', 'armor', 10, 2000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 15, 'Unforged armor of gray SteelTree bark, non-environmental, worn as a full suit or in pieces. -20% to Prowl and similar skills in a full suit, -10% in a half suit, -5% for helmet with arm and leg guards only. +5% to Camouflage. Price varies with availability and craftsmanship; basic plain prices at Char.', 'Rifts World Book 26: Dinosaur Swamp p.80', NULL),
  ('steeltree-bark-armor-arm-bracers', 'SteelTree Bark Armor: Arm Bracers', 'rifts', 'armor', 8, 3000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 18, 'Unforged armor of gray SteelTree bark, non-environmental, worn as a full suit or in pieces. -20% to Prowl and similar skills in a full suit, -10% in a half suit, -5% for helmet with arm and leg guards only. +5% to Camouflage. Price varies with availability and craftsmanship; basic plain prices at Char.', 'Rifts World Book 26: Dinosaur Swamp p.80', NULL),
  ('steeltree-bark-armor-leggings', 'SteelTree Bark Armor: Leggings', 'rifts', 'armor', 12, 4000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 20, 'Unforged armor of gray SteelTree bark, non-environmental, worn as a full suit or in pieces. -20% to Prowl and similar skills in a full suit, -10% in a half suit, -5% for helmet with arm and leg guards only. +5% to Camouflage. Price varies with availability and craftsmanship; basic plain prices at Char.', 'Rifts World Book 26: Dinosaur Swamp p.80', NULL),
  ('steeltree-bark-armor-main-body-chest-plate', 'SteelTree Bark Armor: Main Body/Chest Plate', 'rifts', 'armor', 30, 6000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 40, 'Unforged armor of gray SteelTree bark, non-environmental, worn as a full suit or in pieces. -20% to Prowl and similar skills in a full suit, -10% in a half suit, -5% for helmet with arm and leg guards only. +5% to Camouflage. Price varies with availability and craftsmanship; basic plain prices at Char.', 'Rifts World Book 26: Dinosaur Swamp p.80', NULL),
  ('steeltree-bark-armor-shield', 'SteelTree Bark Armor: Shield', 'rifts', 'armor', 10, 2000, '2,000 (small) to 6,000 (large) credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 15, 'Unforged armor of gray SteelTree bark, non-environmental, worn as a full suit or in pieces. -20% to Prowl and similar skills in a full suit, -10% in a half suit, -5% for helmet with arm and leg guards only. +5% to Camouflage. Price varies with availability and craftsmanship; basic plain prices at Char. The shield has 15 (small) to 40 (large) M.D.C. and weighs 10 to 50 lbs; the small one is stored.', 'Rifts World Book 26: Dinosaur Swamp p.80', NULL),
  ('steeltree-twig-armor-skullcap-helmet', 'SteelTree Twig Armor: Skullcap/Helmet', 'rifts', 'armor', 9, NULL, '30% more than the matching Bark Armor piece; no per-piece price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 30, 'Unforged armor of small SteelTree twigs and bark pieces, protecting as well as alloy or ceramic armor. Weight, penalties and the +5% Camouflage bonus are as SteelTree Bark Armor.', 'Rifts World Book 26: Dinosaur Swamp p.81', NULL),
  ('steeltree-twig-armor-shoulder-pieces', 'SteelTree Twig Armor: Shoulder Pieces', 'rifts', 'armor', 10, NULL, '30% more than the matching Bark Armor piece; no per-piece price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 22, 'Unforged armor of small SteelTree twigs and bark pieces, protecting as well as alloy or ceramic armor. Weight, penalties and the +5% Camouflage bonus are as SteelTree Bark Armor.', 'Rifts World Book 26: Dinosaur Swamp p.81', NULL),
  ('steeltree-twig-armor-arm-bracers', 'SteelTree Twig Armor: Arm Bracers', 'rifts', 'armor', 8, NULL, '30% more than the matching Bark Armor piece; no per-piece price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 28, 'Unforged armor of small SteelTree twigs and bark pieces, protecting as well as alloy or ceramic armor. Weight, penalties and the +5% Camouflage bonus are as SteelTree Bark Armor.', 'Rifts World Book 26: Dinosaur Swamp p.81', NULL),
  ('steeltree-twig-armor-leggings', 'SteelTree Twig Armor: Leggings', 'rifts', 'armor', 12, NULL, '30% more than the matching Bark Armor piece; no per-piece price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 34, 'Unforged armor of small SteelTree twigs and bark pieces, protecting as well as alloy or ceramic armor. Weight, penalties and the +5% Camouflage bonus are as SteelTree Bark Armor.', 'Rifts World Book 26: Dinosaur Swamp p.81', NULL),
  ('steeltree-twig-armor-main-body-chest-plate', 'SteelTree Twig Armor: Main Body/Chest Plate', 'rifts', 'armor', 30, NULL, '30% more than the matching Bark Armor piece; no per-piece price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 56, 'Unforged armor of small SteelTree twigs and bark pieces, protecting as well as alloy or ceramic armor. Weight, penalties and the +5% Camouflage bonus are as SteelTree Bark Armor.', 'Rifts World Book 26: Dinosaur Swamp p.81', NULL),
  ('steeltree-twig-armor-shield', 'SteelTree Twig Armor: Shield', 'rifts', 'armor', 10, NULL, '30% more than the matching Bark Armor piece; no per-piece price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 20, 'Unforged armor of small SteelTree twigs and bark pieces, protecting as well as alloy or ceramic armor. Weight, penalties and the +5% Camouflage bonus are as SteelTree Bark Armor. The shield has 20 (small) to 50 (large) M.D.C. and weighs 10 to 50 lbs; the small one is stored.', 'Rifts World Book 26: Dinosaur Swamp p.81', NULL),
  ('steeltree-leaf-armor', 'SteelTree Leaf Armor', 'rifts', 'armor', 6, 2000, '2,000-4,000 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A cloak, cape or poncho of fallen mature SteelTree leaves, often with a separate helmet. M.D.C. IS ROLLED, so the mdc column is empty: 14+1D6. -5% to Prowl, Climb and similar skills; +10% to Camouflage, +5% to Blend.', 'Rifts World Book 26: Dinosaur Swamp p.81', NULL),
  ('steeltree-ball-and-chain', 'SteelTree Ball & Chain', 'rifts', 'weapon', 4, 250, '250-350 credits.', '2D6 S.D.C.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Average length 3-4 ft, weight 4-6 lbs. Made from SteelTree root and stone. Unforged SteelTree wood, slightly decorated (a raw branch costs nothing). Does S.D.C. damage but can parry M.D. melee weapons, claws and bites; in Supernatural Strength hands it adds half its S.D.C. damage as M.D. to the user''s usual M.D. (2D6 S.D.C. becomes 1D6 M.D.).', 'Rifts World Book 26: Dinosaur Swamp p.81', NULL),
  ('steeltree-club-cudgel-cane', 'SteelTree Club/Cudgel/Cane', 'rifts', 'weapon', 5, 50, '50-100 credits.', '2D4 S.D.C.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Average length 2-3 ft. Unforged SteelTree wood, slightly decorated (a raw branch costs nothing). Does S.D.C. damage but can parry M.D. melee weapons, claws and bites; in Supernatural Strength hands it adds half its S.D.C. damage as M.D. to the user''s usual M.D. (2D6 S.D.C. becomes 1D6 M.D.).', 'Rifts World Book 26: Dinosaur Swamp p.81', NULL);

