  ('steeltree-staff-short', 'SteelTree Staff, Short', 'rifts', 'weapon', 4, 75, '75-200 credits.', '2D4 S.D.C.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Average length 4-5 ft, weight 4-6 lbs. Unforged SteelTree wood, slightly decorated (a raw branch costs nothing). Does S.D.C. damage but can parry M.D. melee weapons, claws and bites; in Supernatural Strength hands it adds half its S.D.C. damage as M.D. to the user''s usual M.D. (2D6 S.D.C. becomes 1D6 M.D.).', 'Rifts World Book 26: Dinosaur Swamp p.81', NULL),
  ('steeltree-war-club-mace', 'SteelTree War Club/Mace', 'rifts', 'weapon', 5, 200, '200-300 credits.', '2D6 S.D.C.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Average length 3 ft, weight 5-8 lbs. Unforged SteelTree wood, slightly decorated (a raw branch costs nothing). Does S.D.C. damage but can parry M.D. melee weapons, claws and bites; in Supernatural Strength hands it adds half its S.D.C. damage as M.D. to the user''s usual M.D. (2D6 S.D.C. becomes 1D6 M.D.).', 'Rifts World Book 26: Dinosaur Swamp p.81', NULL),
  ('steeltree-root-brew', 'SteelTree Root Brew', 'rifts', 'gear', NULL, 20000, '20,000-100,000 credits per dose, by availability; rarely sold or traded.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A drink made only from the underground root of a sapling SteelTree, mostly kept by tribal shamans. After one minute, for 1D4+1 hours, a mortal S.D.C. being gains Superhuman/Robotic (not Supernatural) strength: P.S. +10, M.D. bare hands, M.D.C. equal to (S.D.C. + Hit Points) / 3, fatigue at half rate. Afterwards -2 on all combat moves and -10% to skills for 1D6 hours. Each drink needs a save vs poison 16+; each failure gives a permanent cumulative -1 to later saves vs the brew and a roll on the book''s effects table (hallucinations, tremors, mood swings, alignment reversal, some permanent). Not addictive in itself.', 'Rifts World Book 26: Dinosaur Swamp p.81-82', NULL),
  ('ew-biting-war-club', 'EW Biting War Club', 'rifts', 'weapon', NULL, 20000, '20,000-35,000 credits; common among the barbarian tribes.', 'Activated: blunt 1D4 M.D., teeth 2D4 M.D.; normally 1D6 / 2D4 S.D.C. +P.S.', 1, 'Thrown 80 ft (24.4 m)', NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Paddle-sized club with 10-15 serrated teeth on one face. Activate 4 P.P.E. (8 I.S.P.), 10 minutes. +1 to strike and +2 damage thrown, 80 ft (24.4 m).', 'Rifts World Book 26: Dinosaur Swamp p.84-85', NULL),
  ('ew-battle-claw', 'EW Battle Claw', 'rifts', 'weapon', NULL, 60000, '60,000-75,000 credits for the pair; common among the tribes.', 'Activated: 2D6 M.D.; normally 2D6 S.D.C.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Hide gloves tipped with dinosaur claws, worn as a pair. Activate 10 P.P.E. (20 I.S.P.), 5 minutes. Triple damage on a natural 20 and the target is stunned one melee round. Can parry M.D. bites, claws and melee weapons. Wearer: hand skills -50%, -4 to strike with thrown and projectile weapons, -1 strike and parry with other hand-to-hand weapons.', 'Rifts World Book 26: Dinosaur Swamp p.85', NULL),
  ('ew-bleeder-claws', 'EW Bleeder Claws', 'rifts', 'weapon', NULL, 100000, '100,000 credits for the pair; common among the tribes.', '2D6 S.D.C./Hit Points through M.D.C. armor; 2D6 M.D. to M.D. creatures', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Battle Claw gloves with big hooked Raptor claws. Activate 15 P.P.E. (30 I.S.P.), 1 minute. The damage bypasses M.D.C. body or power armor to hurt the wearer inside (not vehicle or robot occupants); magic armor or fields block it but take 4D6 M.D. Each hit on an unarmored S.D.C. victim adds cumulative -2 initiative, -1 strike, parry and dodge, -5% skills for 3 melee rounds. Wearer penalties as the Battle Claw.', 'Rifts World Book 26: Dinosaur Swamp p.85-86', NULL),
  ('ew-climb-claws', 'EW Climb Claws', 'rifts', 'magic', NULL, 40000, '40,000-50,000 credits for the pair; common.', '1D6 S.D.C./Hit Points', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Five-finger clawed gloves. Activate 5 P.P.E. (10 I.S.P.), 15 minutes. Climb 98% (trees, rough surfaces), 88% (smooth but porous), 58% (smooth); rappel 80%. Touch and dexterity skills -20%; -1 to strike with thrown weapons, bows and guns.', 'Rifts World Book 26: Dinosaur Swamp p.86', NULL),
  ('ew-digger-claws', 'EW Digger Claws', 'rifts', 'magic', NULL, 30000, '30,000-50,000 credits for the pair; not very common.', '1D4 S.D.C./Hit Points +P.S.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Mitten gloves with shovel plates. Activate 15 P.P.E. (30 I.S.P.), 30 minutes. Dig like a badger in dry earth for 1D4 hours; tunnels last at most 1D4 days. Hand skills -80%; throwing and guns impossible; -1 to all combat bonuses.', 'Rifts World Book 26: Dinosaur Swamp p.86', NULL),
  ('ew-basher-mace', 'EW Basher Mace', 'rifts', 'weapon', NULL, 40000, '40,000-55,000 credits; popular among the strongest barbarians.', 'Activated: 4D6+2 M.D.; normally 3D6 S.D.C. +P.S.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Long-handled mace of an Ankylosaurus tail. Activate 8 P.P.E. (16 I.S.P.), 10 minutes. +2 to disarm; 01-40 chance (+10 on a leg hit, 01-75 on a natural 20) to knock down a foe up to 8 ft tall. A critical leg strike cramps a dinosaur under 5 tons (-20% Spd, -1 strike, cumulative). Cannot be thrown. Needs P.S. 21+ one-handed, else -4 strike, parry and disarm.', 'Rifts World Book 26: Dinosaur Swamp p.86-87', NULL),
  ('ew-fang-claw', 'EW Fang Claw (Short Sword)', 'rifts', 'weapon', NULL, 70000, '70,000-90,000 credits; popular only among certain tribes.', 'Activated: 3D6 M.D., +1D6 M.D. per claw to an impaled foe; normally 2D6 S.D.C. +P.S.', 1, 'Thrown 40 ft (12.2 m) at -4', NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Katar-style short sword of dinosaur plate with two movable Raptor claws. Activate 10 P.P.E. (20 I.S.P.), 6 minutes. +2 parry, +2 disarm. A critical or two-handed power stab against an animal, dinosaur or dragon does 5D6 M.D. x3 (as printed). Thrown at -4, 40 ft max. Paired use needs P.P. 21+.', 'Rifts World Book 26: Dinosaur Swamp p.87', NULL),
  ('ew-horror-mace', 'EW Horror Mace', 'rifts', 'weapon', NULL, 60000, '60,000-75,000 credits; fair availability.', 'Activated: 3D6 M.D.; normally 2D6 S.D.C. +P.S.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. A club with rows of large predator teeth. Activate 17 P.P.E. (34 I.S.P.); the illusion lasts one melee round, the M.D. six minutes. All who see the illusion save vs Horror Factor 14+ or suffer H.F. penalties plus -3 strike, parry, dodge and disarm for that melee and -2 initiative the next.', 'Rifts World Book 26: Dinosaur Swamp p.87-88', NULL),
  ('ew-hungry-war-club', 'EW Hungry War Club', 'rifts', 'weapon', NULL, 30000, '30,000-40,000 credits; popular among warriors and raiders.', 'Activated: spiked 3D6+3 M.D., blunt 2D6 M.D.; normally 3D6 / 1D10 S.D.C.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Bone club with three long teeth or spikes. Activate 7 P.P.E. (14 I.S.P.), 10 minutes. +1 parry, +2 disarm. Hooks onto a big dinosaur, chops trails, climbs; often used in pairs.', 'Rifts World Book 26: Dinosaur Swamp p.88', NULL),
  ('ew-panthera-claw', 'EW Panthera Claw', 'rifts', 'weapon', NULL, 15000, '15,000-20,000 credits; popular among bandits and sneaks.', 'Activated: 3D4+3 M.D.; normally 3D4 S.D.C. +P.S.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Fist weapon with three claws or teeth between the fingers and two small end teeth. Activate 5 P.P.E. (10 I.S.P.), 10 minutes. Easy to conceal and palm.', 'Rifts World Book 26: Dinosaur Swamp p.88', NULL),
  ('ew-predator-mask', 'EW Predator Mask', 'rifts', 'magic', NULL, NULL, 'Never sold by a barbarian or Eco-Wizard; would fetch at least 250,000 credits. A mask taken by spilling its owner''s blood becomes inert.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Headdress made from a Raptor or young carnosaur head. Activate 15 P.P.E. (30 I.S.P.), 30 minutes per level of the wearer; cannot be removed while active. Grants Nightvision 60 ft, Identify Tracks 85%, Track 80%, See the Invisible 60 ft and Stalking. At extra cost casts Chameleon, Detect Concealment, Fear, Influence the Beast, Light Target, See Aura and Superhuman Endurance as a 3rd level practitioner.', 'Rifts World Book 26: Dinosaur Swamp p.88-89', NULL),
  ('ew-raptor-claw', 'EW Raptor Claw', 'rifts', 'weapon', NULL, 12000, '12,000-15,000 credits; popular among bandits and sneaks.', 'Activated: 2D4 M.D.; normally 1D6 S.D.C. +P.S.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Fist-held single hooked Raptor claw, also a tool. Activate 5 P.P.E. (10 I.S.P.), 10 minutes. Easy to conceal and palm.', 'Rifts World Book 26: Dinosaur Swamp p.89', NULL),
  ('ew-raptor-tomahawk', 'EW Raptor Tomahawk', 'rifts', 'weapon', NULL, 20000, '20,000-25,000 credits; popular among Wild Knives Warriors, raiders, hunters and scouts.', 'Activated: 2D6 M.D.; normally 2D4 S.D.C. +P.S.', 1, 'Thrown 60 ft (18.3 m)', NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Hand axe with two Raptor claws. Activate 5 P.P.E. (10 I.S.P.), 10 minutes. +1 parry, +2 strike thrown.', 'Rifts World Book 26: Dinosaur Swamp p.89', NULL),
  ('ew-cursed-arrow', 'EW Cursed Arrow', 'rifts', 'weapon', NULL, 8000, '8,000-10,000 credits per arrow; re-enchanting a recovered arrow 5,000 credits and 45 P.P.E.', '1D6 (small bows) or 2D6 (longbows, crossbows), S.D.C. or M.D. by target, plus a Minor Curse', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Stone-headed arrow carrying a Minor Curse (Vertigo and Nausea favored). Activate 10 P.P.E. (20 I.S.P.); the curse lasts 24 hours and is spent on the hit. Save vs magic 14+ (intelligent), 19-20 (animals and dinosaurs), 17+ (familiars and pets); a save halves it and ends it after 1D6 minutes.', 'Rifts World Book 26: Dinosaur Swamp p.90', NULL),
  ('ew-sickness-spear', 'EW Sickness Spear', 'rifts', 'weapon', NULL, 80000, '80,000 credits; common. Re-enchanting 40,000 credits and 90 P.P.E.', '1D6 or 2D4, S.D.C. or M.D. by target, plus Sickness', 1, 'Thrown 100 ft (30.5 m)', NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Spear with a bone, horn, shell, SteelTree or stone blade. Activate 15 P.P.E. (30 I.S.P.); Sickness lasts 12 hours (saves as the Cursed Arrow; a save halves it and ends it after 4D6 minutes). Victim: one attack, endurance -70%, -4 on all combat bonuses, no initiative, skills -40%.', 'Rifts World Book 26: Dinosaur Swamp p.90', NULL),
  ('ew-sinew-net', 'EW Sinew Net', 'rifts', 'magic', NULL, 30000, '30,000 credits; fairly common among hunters, trappers, slavers and barbarians.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. A 10 ft x 10 ft capture net of hide rope, sinew and vertebrae. Activate 8 P.P.E. (16 I.S.P.), 10 minutes. Inactive: 1D4+1 melee rounds to cut out. Active: 50 M.D. to cut one strand; the victim keeps one attack and can use only a small handgun (-6) or M.D. dagger; +4 to disarm a trapped victim.', 'Rifts World Book 26: Dinosaur Swamp p.90-91', NULL),
  ('ew-sinew-sling', 'EW Sinew Sling', 'rifts', 'weapon', NULL, 5000, '5,000-10,000 credits.', 'Activated: 1D4 M.D. small stones, 1D6 M.D. golf-ball size, 2D4 or 1D8 M.D. peach size; normally 1D4 or 1D6 S.D.C.', 1, '200 ft (61 m) activated', NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Leather and sinew sling that folds into a pocket. Activate 3 P.P.E. (6 I.S.P.), two melee rounds. +1 to strike; the target must be visible.', 'Rifts World Book 26: Dinosaur Swamp p.91', NULL),
  ('ew-skin-blanket', 'EW Skin Blanket', 'rifts', 'magic', NULL, 35000, '35,000-50,000 credits; fair availability in barbarian communities only.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. A dinosaur-skin blanket about 5x6 ft that becomes a Carpet of Adhesion. Activate 6 P.P.E. (12 I.S.P.), four minutes. Arms covered: no strike, parry or disarm. Head covered: blind, -10 on combat rolls. Feet stuck: Spd 0, -6 dodge, -2 parry and disarm.', 'Rifts World Book 26: Dinosaur Swamp p.91', NULL),
  ('ew-skin-and-bone-armor', 'EW Skin & Bone Armor', 'rifts', 'armor', NULL, 70000, '70,000-90,000 credits; good availability in barbarian communities only.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Hooded poncho with bone plating, shoulder pads, vambraces and leg guards; light, no movement penalty. M.D.C. IS ROLLED, so the mdc column is empty: 2D6+20 main body, 1D6+8 head. 5 P.P.E. adds 20 M.D.C. (Armor of Ithan) for six minutes. One built-in cloaking spell (Chameleon, Cloak of Darkness, Invisibility: Simple or Multiple Image) costs 6 or 7 P.P.E. more; the book gives its duration as six minutes and as five.', 'Rifts World Book 26: Dinosaur Swamp p.91-92', NULL),
  ('ew-skin-skull-and-plate-armor', 'EW Skin, Skull & Plate Armor', 'rifts', 'armor', NULL, 100000, '100,000-150,000 credits; good availability in barbarian communities only.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Dinosaur-skull helmet, hide mantle and 2-4 plates, as light as a sweater. M.D.C. IS ROLLED, so the mdc column is empty: 6D6+68 main body, 3D6+32 head (the activation line on the same page prints the base as 6D6+66). 5 P.P.E. adds 20 M.D.C. (Armor of Ithan) and Breathe Without Air for six minutes, making it environmental.', 'Rifts World Book 26: Dinosaur Swamp p.92', NULL),
  ('ew-spoil-bomb', 'EW Spoil Bomb', 'rifts', 'magic', NULL, 9000, '9,000 credits each; poor availability even among the tribes.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. A bladder of swamp mud, thrown and destroyed on use. Activate 8 P.P.E. (16 I.S.P.); releases one melee round after activation or on impact, working as the Spoil invocation: spoils food and taints standing water in a 25 ft (7.62 m) radius.', 'Rifts World Book 26: Dinosaur Swamp p.92', NULL),
  ('ew-stegosaur-battle-axe', 'EW Stegosaur Battle Axe', 'rifts', 'weapon', NULL, 30000, '30,000-36,000 credits; popular among barbarian warriors, raiders and scouts.', 'Activated: blade 3D6 M.D., spike 1D6 M.D., blunt 1D4 M.D.; two-handed power strike 6D6 M.D.; the same dice as S.D.C. normally', 1, 'Thrown 60 ft (18.3 m)', NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Axe of Stegosaur plate topped with a tail spike. Activate 7 P.P.E. (14 I.S.P.), 10 minutes. +1 strike, +1 disarm.', 'Rifts World Book 26: Dinosaur Swamp p.92-93', NULL),
  ('ew-stegosaur-knives-and-swords', 'EW Stegosaur Knives & Swords', 'rifts', 'weapon', NULL, 7000, '7,000-15,000 credits; virtually all barbarians own at least one.', 'Activated: knives 1D4 or 1D6 M.D., short swords 1D6 or 2D4, long swords 2D4 or 2D6, two-handed swords 3D6 M.D.; the same dice as S.D.C. normally', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Blades of Stegosaur bone, plate or tail spike in four sizes. Activate 5 P.P.E. (10 I.S.P.), 20 minutes. A large two-handed sword is one-handed only with P.S. 22+ or Supernatural Strength.', 'Rifts World Book 26: Dinosaur Swamp p.93', NULL),
  ('ew-stegosaurs-might', 'EW Stegosaur''s Might', 'rifts', 'weapon', NULL, 80000, '80,000-90,000 credits; uncommon.', 'Activated: spade 3D6+3 M.D. (double to rock, earth and wood), claws 2D6 M.D., blunt 1D6 M.D.; power strike 6D6+3 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Spade, sickle and Raptor-claw polearm of Stegosaurus plate. Activate 8 P.P.E. (16 I.S.P.), 10 minutes. +1 strike. -3 on all combat moves for a user under P.S. 12 or under five feet tall.', 'Rifts World Book 26: Dinosaur Swamp p.93-94', NULL),
  ('ew-stegosaur-spear', 'EW Stegosaur Spear', 'rifts', 'weapon', NULL, 12000, '12,000-16,000 credits; common among all the tribes.', 'Activated: 2D6 M.D. (3D6 with a long tail-spike head), blunt 1D4 M.D.; the same dice as S.D.C. normally', 1, 'Thrown 200 ft (61 m)', NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Spear headed with Stegosaurus spike, plate or bone. Activate 7 P.P.E. (14 I.S.P.), 15 minutes. +1 strike thrown.', 'Rifts World Book 26: Dinosaur Swamp p.94', NULL),
  ('ew-stegosaur-vengeance', 'EW Stegosaur Vengeance (Fire Pick)', 'rifts', 'weapon', NULL, 60000, '60,000-75,000 credits; popular among warriors, raiders and scouts.', 'Activated: pick 2D6 M.D., blunt 1D4 M.D., power strike 4D6 M.D.; Fire Strike +2D6 M.D.; Fireblast 3D6 M.D.; Fire Ball 4D6 M.D.', 1, 'Fireblast 50 ft (15.2 m); Fire Ball 200 ft (61 m)', NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. War pick of a Stegosaurus tail spike that throws fire. Activate 10 P.P.E. (20 I.S.P.), 5 minutes. +1 disarm. Each blast uses one melee action.', 'Rifts World Book 26: Dinosaur Swamp p.94', NULL),
  ('ew-stegosaur-trident', 'EW Stegosaur Trident', 'rifts', 'weapon', NULL, 25000, '25,000-30,000 credits; mostly Wild Knives Warriors, raiders and bandits.', 'Activated: forked end 4D6 M.D., blunt 1D4 M.D.; the same dice as S.D.C. normally', 1, 'Thrown 150 ft (46 m)', NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Trident of three Stegosaurus tail spikes. Activate 10 P.P.E. (20 I.S.P.), 10 minutes. +1 parry, +1 entangle or trip, +2 disarm.', 'Rifts World Book 26: Dinosaur Swamp p.94-95', NULL),
  ('ew-thunder-horn-spear', 'EW Thunder Horn Spear (or Pike)', 'rifts', 'weapon', NULL, 45000, '45,000-55,000 credits; mostly Wild Knives Warriors and hunters.', 'Activated: horn end 4D6 M.D., blunt 1D6 M.D.; the same dice as S.D.C. normally', 1, 'Thrown 200 ft (61 m)', NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. Spear or pike headed with a Triceratops-type horn. Activate 10 P.P.E. (20 I.S.P.), 10 minutes. +1 parry, +1 strike thrown. A hit sounds a thunderclap: wild animals struck get -1 on all combat rolls and lose initiative and an attack; herds scatter.', 'Rifts World Book 26: Dinosaur Swamp p.95', NULL),
  ('ew-thunder-and-lightning-spear', 'EW Thunder & Lightning Spear', 'rifts', 'weapon', NULL, 80000, '80,000-100,000 credits; mostly Wild Knives Warriors and hunters.', 'Activated: horn end 4D6 M.D., blunt 1D6 M.D.; lightning +3D6 M.D. on a hit; Electric Arc 2D6 M.D.', 1, 'Thrown 200 ft (61 m); Electric Arc 50 ft (15.2 m)', NULL, NULL, NULL, NULL, NULL, 'Eco-Wizard item: no glass, metal or technology; anyone with the P.P.E. (or double in I.S.P.) can activate it. The Thunder Horn Spear with bleached wood and feathers, adding lightning. Activate 12 P.P.E. (24 I.S.P.), five minutes. +1 strike thrown; thunderclap as the Thunder Horn Spear. May also be made as a Thunder and Lightning Trident with the same stats and cost.', 'Rifts World Book 26: Dinosaur Swamp p.95-96', NULL),
  ('tw-animal-repellent-whistle-clickers', 'TW Animal Repellent (Whistle Clickers)', 'rifts', 'gear', NULL, 30000, 'Good availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A whistle and clicker pair with a quartz crystal. The whistle works as Repel Animals (3 P.P.E. or 6 I.S.P.) and the clicker as Thunderclap (2 P.P.E. or 4 I.S.P.). The device has 1D6 M.D.C.', 'Rifts World Book 26: Dinosaur Swamp p.96', NULL),
  ('tw-cleansing-bowl', 'TW Cleansing Bowl', 'rifts', 'gear', NULL, 80000, 'Fair to good availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 10, 'A bowl or pot with a caged quartz crystal, working as Cleanse: dry-washing the hands in it cleans the whole body, and laundry put in comes out washed. Activate 6 P.P.E. (12 I.S.P.).', 'Rifts World Book 26: Dinosaur Swamp p.96', NULL),
  ('tw-food-and-water-purifier', 'TW Food & Water Purifier', 'rifts', 'gear', NULL, 40000, '40,000-50,000 credits; good availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 10, 'A lidded pot ringed with rubies, working as Purification on what it holds (typically 2-5 gallons), but not radiation; it can also flash-cook food and flash-boil water. Food spoiled more than 10 days cannot be restored. Activate 20 P.P.E. (40 I.S.P.). 10-40 M.D.C. by size (the low end stored).', 'Rifts World Book 26: Dinosaur Swamp p.96-97', NULL),
  ('tw-ghillie-suit', 'TW Ghillie Suit', 'rifts', 'gear', NULL, 300000, '300,000-500,000 credits; fair availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 18, 'Any garment laced with wire mesh and three emeralds, looking like a hand-made ghillie suit. Activate 10 P.P.E. (20 I.S.P.), 20 minutes: Chameleon and a Globe of Silence covering the wearer, +20% to Camouflage and Blend and +15 to Prowl (as printed). 18 M.D.C. main body. A separate item from the plain Ghillie Suit (printed 59).', 'Rifts World Book 26: Dinosaur Swamp p.97', NULL),
  ('tw-lantern-pole-lantern-light', 'TW Lantern Pole (Lantern Light)', 'rifts', 'gear', NULL, 10000, 'Good availability; a weighted base 10 credits more.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 12, 'A 5-7 ft pole topped with a wire-mesh lantern and quartz crystal, working as Lantern Light for 4 hours on 2 P.P.E. (4 I.S.P.); dims by up to half; works in rain and underwater. Lantern 12 M.D.C., pole 18 M.D.C.', 'Rifts World Book 26: Dinosaur Swamp p.97', NULL),
  ('tw-lantern-pole-globe-of-daylight', 'TW Lantern Pole (Globe of Daylight)', 'rifts', 'gear', NULL, 20000, '20,000-25,000 credits; a weighted base 10 credits more.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 12, 'The Lantern Pole working as Globe of Daylight for 2 hours on 4 P.P.E. (8 I.S.P.), which also keeps off vampires and other sunlight-averse beings. Lantern 12 M.D.C., pole 18 M.D.C.', 'Rifts World Book 26: Dinosaur Swamp p.97', NULL),
  ('tw-med-shooter', 'TW Med-Shooter', 'rifts', 'gear', NULL, 50000, '50,000 credits for the dispenser, plus each Medical Crystal; poor availability of both.', NULL, 0, 'Touch', NULL, NULL, NULL, NULL, 2, 'A modified Compu-Drug Dispenser holding three Medical Crystals in a rotating cylinder, each crystal with two charges; neither works without the other. Touch range; effects as cast by a 5th level mage; save vs magic 14+ at -2. Recharging a crystal costs the spell''s P.P.E. +70, usually 75% of its two-dose price.', 'Rifts World Book 26: Dinosaur Swamp p.97-98', NULL);

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('tw-med-shooter-crystal-agony', 'TW Med-Shooter Crystal: Agony', 'rifts', 'gear', NULL, 400000, 'Per two-dose crystal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Yellow or Brown Diamond Medical Crystal for the TW Med-Shooter carrying Agony (spell 20 P.P.E.). Activate 16 P.P.E. or 32 I.S.P.. Two charges.', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-med-shooter-crystal-blind', 'TW Med-Shooter Crystal: Blind', 'rifts', 'gear', NULL, 300000, 'Per two-dose crystal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Black Sapphire Medical Crystal for the TW Med-Shooter carrying Blind (spell 6 P.P.E.). Activate 10 P.P.E. or 20 I.S.P.. Two charges.', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-med-shooter-crystal-breathe-without-air', 'TW Med-Shooter Crystal: Breathe Without Air', 'rifts', 'gear', NULL, 200000, 'Per two-dose crystal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Blue Sapphire Medical Crystal for the TW Med-Shooter carrying Breathe Without Air (spell 5 P.P.E.). Activate 3 P.P.E. or 6 I.S.P.; 10 minute duration. Two charges.', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-med-shooter-crystal-cure-illness', 'TW Med-Shooter Crystal: Cure Illness', 'rifts', 'gear', NULL, 500000, 'Per two-dose crystal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Rose Quartz Medical Crystal for the TW Med-Shooter carrying Cure Illness (spell 15 P.P.E.). Activate 10 P.P.E. or 20 I.S.P.. Two charges.', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-med-shooter-crystal-cure-minor-disorders', 'TW Med-Shooter Crystal: Cure Minor Disorders', 'rifts', 'gear', NULL, 200000, 'Per two-dose crystal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Garnet Medical Crystal for the TW Med-Shooter carrying Cure Minor Disorders (spell 10 P.P.E.). Activate 8 P.P.E. or 16 I.S.P.. Two charges.', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-med-shooter-crystal-domination', 'TW Med-Shooter Crystal: Domination', 'rifts', 'gear', NULL, 200000, 'Per two-dose crystal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Amethyst Quartz Medical Crystal for the TW Med-Shooter carrying Domination (spell 10 P.P.E.). Activate 10 P.P.E. or 20 I.S.P.. Two charges.', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-med-shooter-crystal-fear', 'TW Med-Shooter Crystal: Fear', 'rifts', 'gear', NULL, 170000, 'Per two-dose crystal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Green Crystal Medical Crystal for the TW Med-Shooter carrying Fear (spell 5 P.P.E.). Activate 5 P.P.E. or 10 I.S.P.. Two charges.', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-med-shooter-crystal-fortify-against-disease', 'TW Med-Shooter Crystal: Fortify Against Disease', 'rifts', 'gear', NULL, 100000, 'Per two-dose crystal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Red Agate Medical Crystal for the TW Med-Shooter carrying Fortify Against Disease (spell 15 P.P.E.). Activate 10 P.P.E. or 20 I.S.P.. Two charges.', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-med-shooter-crystal-hallucination', 'TW Med-Shooter Crystal: Hallucination', 'rifts', 'gear', NULL, 200000, 'Per two-dose crystal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Star Sapphire Medical Crystal for the TW Med-Shooter carrying Hallucination (spell 30 P.P.E.). Activate 25 P.P.E. or 50 I.S.P.. Two charges.', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-med-shooter-crystal-light-healing', 'TW Med-Shooter Crystal: Light Healing', 'rifts', 'gear', NULL, 80000, 'Per two-dose crystal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Ruby Quartz Medical Crystal for the TW Med-Shooter carrying Light Healing (spell 6 P.P.E.). Activate 3 P.P.E. or 6 I.S.P.. Two charges.', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-med-shooter-crystal-negate-poison-toxin', 'TW Med-Shooter Crystal: Negate Poison/Toxin', 'rifts', 'gear', NULL, 50000, 'Per two-dose crystal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Topaz Medical Crystal for the TW Med-Shooter carrying Negate Poison/Toxin (spell 5 P.P.E.). Activate 3 P.P.E. or 6 I.S.P.. Two charges.', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-med-shooter-crystal-paralysis-lesser', 'TW Med-Shooter Crystal: Paralysis: Lesser', 'rifts', 'gear', NULL, 100000, 'Per two-dose crystal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Smoky Quartz Medical Crystal for the TW Med-Shooter carrying Paralysis: Lesser (spell 5 P.P.E.). Activate 3 P.P.E. or 6 I.S.P.. Two charges.', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-med-shooter-crystal-sleep', 'TW Med-Shooter Crystal: Sleep', 'rifts', 'gear', NULL, 100000, 'Per two-dose crystal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Pink Quartz or Sapphire Medical Crystal for the TW Med-Shooter carrying Sleep (spell 10 P.P.E.). Activate 8 P.P.E. or 16 I.S.P.. Two charges.', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-med-shooter-crystal-trance', 'TW Med-Shooter Crystal: Trance', 'rifts', 'gear', NULL, 150000, 'Per two-dose crystal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Citrine Quartz Medical Crystal for the TW Med-Shooter carrying Trance (spell 10 P.P.E.). Activate 10 P.P.E. or 20 I.S.P.. Two charges.', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-shelter-small-medium', 'TW Shelter (Small & Medium)', 'rifts', 'gear', NULL, 40000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 50, 'Metal tent stakes topped with red agates, working as Sheltering Force and Lantern Light for 24 hours: a tent that cannot tear and resists fire and snow, with one dimmable light at the peak. Each stake has 30 M.D.C.; stakes must stay within range of each other. Sleeps 2 or 4. Activate 10 P.P.E. (20 I.S.P.). Small 50 M.D.C., medium 100 (the small stored).', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-shelter-large', 'TW Shelter (Large)', 'rifts', 'gear', NULL, 80000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 150, 'Metal tent stakes topped with red agates, working as Sheltering Force and Lantern Light for 24 hours: a tent that cannot tear and resists fire and snow, with one dimmable light at the peak. Each stake has 30 M.D.C.; stakes must stay within range of each other. Sleeps 6. Activate 20 P.P.E. (40 I.S.P.).', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-shelter-very-large-hut', 'TW Shelter (Very Large/Hut)', 'rifts', 'gear', NULL, 130000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 200, 'Metal tent stakes topped with red agates, working as Sheltering Force and Lantern Light for 24 hours: a tent that cannot tear and resists fire and snow, with one dimmable light at the peak. Each stake has 30 M.D.C.; stakes must stay within range of each other. A hut for 8-12. Activate 40 P.P.E. (80 I.S.P.).', 'Rifts World Book 26: Dinosaur Swamp p.98', NULL),
  ('tw-sustain-belt', 'TW Sustain Belt', 'rifts', 'gear', NULL, 350000, 'Poor to fair availability at cities of magic; rare versions with Dimensional Pocket pouches cost 3-10x.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 2, 'A utility belt, web vest or harness set with six emeralds, working as Sustain for 48 hours per activation of 25 P.P.E. (50 I.S.P.); the magic stops at once if it comes off. 2-8 M.D.C. by size (the low end stored).', 'Rifts World Book 26: Dinosaur Swamp p.98-99', NULL),
  ('tw-watchguard-pole', 'TW Watchguard Pole', 'rifts', 'gear', NULL, 40000, '40,000 credits a pole, +10,000 if also a Lantern Pole; poor to fair availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 12, 'A pole with a large Alexandrite, working as Watchguard for 8 hours on 7 P.P.E. (14 I.S.P.): it detects anything dog-sized or larger entering its area, tells the activator where and roughly how many, and flashes a strobe seen within 100 yards. Lantern 12 M.D.C., pole 16 M.D.C.', 'Rifts World Book 26: Dinosaur Swamp p.99', NULL),
  ('tw-water-well', 'TW Water Well', 'rifts', 'gear', NULL, 175000, 'Poor to fair availability at cities of magic.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 60, 'A tripod hand pump with a catch basin and six aquamarines, working as Create Water: up to 10 gallons (37.8 liters) of fresh water per activation of 10 P.P.E. (20 I.S.P.).', 'Rifts World Book 26: Dinosaur Swamp p.99', NULL),
  ('necromancy-dinosaur-skull-large-predator', 'Necromancy: Dinosaur Skull (T-Rex/Large Predator)', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 30. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 20, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. Worn as a helmet: 20 M.D.C.; +4 to the Necromancer''s Horror Factor; +8 to save vs Horror Factor; +4 to save vs disease and poison; track by blood scent or decaying flesh 85%; casts Domination (5 P.P.E.); bite 3D6 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.100', NULL),
  ('necromancy-dinosaur-skull-small-predator', 'Necromancy: Dinosaur Skull (Raptor/Small Predator)', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 20. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 8, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. Worn as a helmet: 8 M.D.C.; +1 to Horror Factor; +4 to save vs Horror Factor; track by blood scent or decaying flesh 70%; bite 1D6 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.100', NULL),
  ('necromancy-dinosaur-skull-sauropod', 'Necromancy: Dinosaur Skull (Sauropod/Herbivore)', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 20. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 30, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. Worn as a helmet: 30 M.D.C.; +5 to save vs disease and poison; head butt 1D4 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.100', NULL),
  ('necromancy-dinosaur-skull-horned-herbivore', 'Necromancy: Dinosaur Skull (Triceratops/Horned Herbivore)', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 25. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 20, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. Worn as a helmet: 20 M.D.C.; +3 to save vs disease and poison; head butt 2D6 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.100', NULL),
  ('necromancy-dinosaur-limbs-predator', 'Necromancy: Dinosaur Limbs/Feet (Predator)', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 25. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. +15 Spd; a burst of double running speed for one melee round; leap 20 ft high or long; kick 2D6 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.100', NULL),
  ('necromancy-dinosaur-limbs-running-herbivore', 'Necromancy: Dinosaur Limbs/Feet (Running Herbivore)', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 35. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. +25 Spd; leap 30 ft high or long; +2 to dodge.', 'Rifts World Book 26: Dinosaur Swamp p.100', NULL),
  ('necromancy-dinosaur-limbs-sauropod', 'Necromancy: Dinosaur Limbs/Feet (Sauropod)', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 40. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. +8 Spd; excellent balance; senses low-frequency ground vibration (explosions, quakes, stampedes, robot vehicles) from 30 miles; kick 1D6 M.D., stomp 1D6+3 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.100', NULL),
  ('necromancy-dinosaur-forearm-claws-large-predator', 'Necromancy: Dinosaur Forearm Claws (T-Rex/Large Predator)', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 25. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. +1 strike and parry; punch 1D4 M.D.; +2 P.S. No opposable thumb: -50% with modern vehicles and machines, -5 to strike with guns.', 'Rifts World Book 26: Dinosaur Swamp p.100', NULL),
  ('necromancy-dinosaur-forearm-claws-small-predator', 'Necromancy: Dinosaur Forearm Claws (Raptor/Small Predator)', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 35. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. +2 strike and parry; punch 1D6 M.D.; +2 P.P.; +10% Climb. Partial thumbs: -15% with machines and vehicles, -2 to strike with guns.', 'Rifts World Book 26: Dinosaur Swamp p.100', NULL),
  ('necromancy-dinosaur-forearm-claws-bipedal-herbivore', 'Necromancy: Dinosaur Forearm Claws (Running Bipedal Herbivore)', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 25. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. +2 parry and entangle; punch 1D4 M.D.; +2 P.E. Partial thumbs: -15% with machines and vehicles, -2 to strike with guns.', 'Rifts World Book 26: Dinosaur Swamp p.100', NULL),
  ('necromancy-dinosaur-tail-predator', 'Necromancy: Dinosaur Tail (Predator)', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 25. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. +20% to balance; +3 roll with impact; +1 dodge; +5 Spd; one extra attack per melee; tail strike 1D6 M.D.', 'Rifts World Book 26: Dinosaur Swamp p.100', NULL),
  ('necromancy-dinosaur-tail-herbivore', 'Necromancy: Dinosaur Tail (Herbivore)', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 25. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. +2 roll with impact; +3 Spd; one extra attack per melee; tail strike 1D4 (printed M.D.C.) from a small tail, 3D4 M.D. from a long, thick or whip-like tail, 3D6 M.D. from a bony club or spiked tail.', 'Rifts World Book 26: Dinosaur Swamp p.100', NULL),
  ('necromancy-dinosaur-armored-spikes-limbs', 'Necromancy: Dinosaur Armored Spikes, Spines & Plates (Limbs)', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 35. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 20, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. At least two limbs armored: 20 M.D.C.; +2 roll with impact; +1 P.E.; +1 save vs magic; punch or kick +1D6 M.D. Adds 50 lbs; -6 Spd; -5% to Acrobatics, Gymnastics, Climbing, Swimming and Prowl. Stacks with the torso.', 'Rifts World Book 26: Dinosaur Swamp p.100', NULL),
  ('necromancy-dinosaur-armored-spikes-torso', 'Necromancy: Dinosaur Armored Spikes, Spines & Plates (Torso)', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 50. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 30, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. Torso and body: 30 M.D.C.; +2 roll with impact; +2 P.E.; +1 save vs magic; +2 save vs poison; body block 1D6 M.D. Adds 50 lbs; -10 Spd; -15% to the same mobility skills. Stacks with the limbs.', 'Rifts World Book 26: Dinosaur Swamp p.100-101', NULL),
  ('necromancy-dinosaur-tongue-predator', 'Necromancy: Dinosaur Tongue (Predator)', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 17. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. An air-shattering roar exactly like Thunderclap (2 P.P.E.); track by scent 35% (+10% for blood).', 'Rifts World Book 26: Dinosaur Swamp p.101', NULL),
  ('necromancy-dinosaur-tongue-herbivore', 'Necromancy: Dinosaur Tongue (Herbivore)', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 10. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. Locates fresh drinkable water within one mile at 75%; +15% to identify herbs, fruits, plants and poison by taste.', 'Rifts World Book 26: Dinosaur Swamp p.101', NULL),
  ('necromancy-dinosaur-wings', 'Necromancy: Dinosaur/Pterosaur Wings', 'rifts', 'magic', NULL, NULL, 'P.P.E. Cost: 35. No credit price printed.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A dinosaur body part a Necromancer enchants and wears; adult parts shrink to fit. Strapped to the back; must span at least the Necromancer''s height. Flight up to 40 mph (64 km); running speed and all combat bonuses reduced 50%.', 'Rifts World Book 26: Dinosaur Swamp p.101', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
